const parseJson = (raw, fallback) => {
  try {
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
};

const env = process.env;
const defaultLeadSource = {
  mode: 'static',
  maxBatchSize: 1,
  maxRetries: 2,
  retryDelayMinutes: 15,
  testLeads: [
    { id: 'lead-human-1', name: 'Human Test Lead', phone: '+15550000001', company: 'Acme Human', status: 'new', attempts: 0, last_result: null, last_called_at: null },
    { id: 'lead-voicemail-1', name: 'Voicemail Test Lead', phone: '+15550000002', company: 'Acme Voicemail', status: 'new', attempts: 0, last_result: null, last_called_at: null },
    { id: 'lead-busy-1', name: 'Busy Test Lead', phone: '+15550000003', company: 'Acme Busy', status: 'new', attempts: 0, last_result: null, last_called_at: null },
    { id: 'lead-no-answer-1', name: 'No Answer Test Lead', phone: '+15550000004', company: 'Acme No Answer', status: 'new', attempts: 0, last_result: null, last_called_at: null },
    { id: 'lead-duplicate-1', name: 'Duplicate Webhook Test Lead', phone: '+15550000005', company: 'Acme Duplicate', status: 'new', attempts: 0, last_result: null, last_called_at: null },
    { id: 'lead-transfer-fail-1', name: 'Transfer Failure Test Lead', phone: '+15550000006', company: 'Acme Transfer Failure', status: 'new', attempts: 0, last_result: null, last_called_at: null }
  ]
};
const defaultStorage = {
  mode: 'workflow_static',
  processedEventTtlHours: 168,
  maxEventHistoryPerAttempt: 25,
  maxLogs: 500
};
const leadSource = parseJson(env.LEAD_SOURCE_CONFIG, defaultLeadSource);
const storage = parseJson(env.STORAGE_CONFIG, defaultStorage);
const baseInput = env.N8N_PUBLIC_WEBHOOK_URL || 'https://YOUR_N8N_HOST';
const publicWebhookBase = baseInput.replace(/\/$/, '').replace(/\/webhook\/.*$/, '');

return [{
  json: {
    config: {
      telnyxApiBase: 'https://api.telnyx.com/v2',
      telnyxApiKey: env.TELNYX_API_KEY || 'TELNYX_API_KEY',
      telnyxConnectionId: env.TELNYX_CONNECTION_ID || 'TELNYX_CONNECTION_ID',
      telnyxFromNumber: env.TELNYX_FROM_NUMBER || 'TELNYX_FROM_NUMBER',
      myPhoneNumber: env.MY_PHONE_NUMBER || 'MY_PHONE_NUMBER',
      publicWebhookBase,
      telnyxWebhookUrl: publicWebhookBase + '/webhook/telnyx-power-dialer-events',
      leadSource,
      storage,
      maxRetries: Number(leadSource.maxRetries ?? 2),
      retryDelayMinutes: Number(leadSource.retryDelayMinutes ?? 15),
      maxBatchSize: Number(leadSource.maxBatchSize ?? 1),
      humanResults: ['human', 'human_residence', 'human_business'],
      nonHumanResults: ['machine', 'silence', 'fax_detected', 'not_sure'],
      busyCauses: ['busy', 'user_busy'],
      noAnswerCauses: ['no_answer', 'timeout', 'no_response'],
      invalidCauses: ['unallocated_number', 'invalid_number_format', 'no_route_destination'],
      failedCauses: ['call_rejected', 'service_unavailable', 'incompatible_destination', 'system_shutdown', 'normal_temp_failure']
    },
    trigger: $input.first() ? $input.first().json : {}
  }
}];

const config = $json.config;
if ((config.leadSource.mode || 'static') !== 'static') {
  throw new Error('This workflow ships with the static lead adapter enabled. Replace the node named Lead Source - Static Test List with your Google Sheets, Airtable, or Supabase source and keep the same lead JSON shape.');
}

const leads = Array.isArray(config.leadSource.testLeads) ? config.leadSource.testLeads : [];
return leads.map((lead) => ({
  json: {
    config,
    lead: {
      id: String(lead.id),
      name: lead.name || '',
      phone: lead.phone || '',
      company: lead.company || '',
      status: lead.status || 'new',
      attempts: Number(lead.attempts || 0),
      last_result: lead.last_result ?? null,
      last_called_at: lead.last_called_at ?? null
    }
  }
}));

const staticData = $getWorkflowStaticData('global');
staticData.dialer = staticData.dialer || { leads: {}, attempts: {}, processedEvents: {}, logs: [] };
const store = staticData.dialer;
const config = $input.first().json.config;
const inputLeads = $input.all().map((item) => item.json.lead);
const now = new Date();

for (const lead of inputLeads) {
  const existing = store.leads[lead.id] || {};
  store.leads[lead.id] = {
    id: lead.id,
    name: lead.name || existing.name || '',
    phone: lead.phone || existing.phone || '',
    company: lead.company || existing.company || '',
    status: existing.status ?? lead.status ?? 'new',
    attempts: Number(existing.attempts ?? lead.attempts ?? 0),
    last_result: existing.last_result ?? lead.last_result ?? null,
    last_called_at: existing.last_called_at ?? lead.last_called_at ?? null,
    next_retry_at: existing.next_retry_at ?? null,
    current_attempt_id: existing.current_attempt_id ?? null,
    active_call_control_id: existing.active_call_control_id ?? null,
    transfer_happened: Boolean(existing.transfer_happened ?? false),
    updated_at: existing.updated_at ?? null
  };
}

const eligible = Object.values(store.leads)
  .filter((lead) => {
    if (!lead.phone || !lead.id) return false;
    if (lead.status === 'do_not_call') return false;
    if (['dialing', 'call_initiated', 'answered', 'amd_human', 'transfer_requested'].includes(lead.status)) return false;
    if (lead.status === 'retry_scheduled') {
      return lead.next_retry_at ? new Date(lead.next_retry_at) <= now : true;
    }
    return ['new', 'ready', 'queued', '', null, undefined].includes(lead.status);
  })
  .sort((a, b) => {
    const left = a.next_retry_at || a.last_called_at || '0000';
    const right = b.next_retry_at || b.last_called_at || '0000';
    return left.localeCompare(right) || String(a.id).localeCompare(String(b.id));
  });

if (!eligible.length) {
  return [{
    json: {
      config,
      has_eligible_lead: false,
      message: 'No eligible leads to dial right now'
    }
  }];
}

return [{
  json: {
    config,
    has_eligible_lead: true,
    lead: eligible[0]
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.dialer = staticData.dialer || { leads: {}, attempts: {}, processedEvents: {}, logs: [] };
const store = staticData.dialer;
const config = $json.config;
const lead = $json.lead;
const nowIso = new Date().toISOString();
const leadState = store.leads[lead.id] || lead;
const attemptNumber = Number(leadState.attempts || 0) + 1;
const attemptId = lead.id + '-attempt-' + attemptNumber;
const clientStatePayload = {
  lead_id: lead.id,
  attempt_id: attemptId,
  attempt_number: attemptNumber,
  lead_name: lead.name,
  lead_phone: lead.phone,
  company: lead.company,
  created_at: nowIso
};
const clientState = Buffer.from(JSON.stringify(clientStatePayload)).toString('base64');

store.attempts[attemptId] = {
  attempt_id: attemptId,
  attempt_number: attemptNumber,
  lead_id: lead.id,
  lead_name: lead.name,
  lead_phone: lead.phone,
  company: lead.company,
  client_state: clientState,
  client_state_payload: clientStatePayload,
  status: 'dialing',
  last_result: null,
  initiated_at: nowIso,
  call_control_id: null,
  call_session_id: null,
  call_leg_id: null,
  transfer: {
    status: 'not_requested'
  },
  history: []
};

store.leads[lead.id] = {
  ...leadState,
  status: 'dialing',
  attempts: attemptNumber,
  last_called_at: nowIso,
  next_retry_at: null,
  current_attempt_id: attemptId,
  active_call_control_id: null,
  transfer_happened: false,
  updated_at: nowIso
};

store.logs.unshift({
  at: nowIso,
  kind: 'attempt_prepared',
  lead_id: lead.id,
  attempt_id: attemptId,
  phone: lead.phone
});
store.logs = store.logs.slice(0, Number(config.storage.maxLogs || 500));

return [{
  json: {
    config,
    lead,
    attempt: store.attempts[attemptId]
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.dialer = staticData.dialer || { leads: {}, attempts: {}, processedEvents: {}, logs: [] };
const store = staticData.dialer;
const prepared = $('Prepare Call Attempt').first().json;
const attemptId = prepared.attempt.attempt_id;
const attempt = store.attempts[attemptId] || prepared.attempt;
const lead = store.leads[attempt.lead_id] || prepared.lead;
const input = $input.first().json;
const nowIso = new Date().toISOString();
const errorMessage = input.error?.message || input.error || input.message || null;
const responseData = input.data || input;

if (errorMessage || !responseData.call_control_id) {
  attempt.status = 'failed';
  attempt.last_result = 'failed_to_start';
  attempt.final_result = 'failed_to_start';
  attempt.completed_at = nowIso;
  attempt.start_error = errorMessage || 'Missing call_control_id in Telnyx response';
  store.attempts[attemptId] = attempt;
  store.leads[attempt.lead_id] = {
    ...lead,
    status: 'failed',
    last_result: 'failed_to_start',
    current_attempt_id: null,
    active_call_control_id: null,
    updated_at: nowIso
  };
  store.logs.unshift({
    at: nowIso,
    kind: 'call_start_failed',
    lead_id: attempt.lead_id,
    attempt_id: attemptId,
    error: attempt.start_error
  });
} else {
  attempt.status = 'call_initiated';
  attempt.call_control_id = responseData.call_control_id;
  attempt.call_session_id = responseData.call_session_id || null;
  attempt.call_leg_id = responseData.call_leg_id || null;
  attempt.telnyx_response = responseData;
  store.attempts[attemptId] = attempt;
  store.leads[attempt.lead_id] = {
    ...lead,
    status: 'call_initiated',
    active_call_control_id: responseData.call_control_id,
    current_attempt_id: attemptId,
    updated_at: nowIso
  };
  store.logs.unshift({
    at: nowIso,
    kind: 'call_initiated',
    lead_id: attempt.lead_id,
    attempt_id: attemptId,
    call_control_id: responseData.call_control_id
  });
}
store.logs = store.logs.slice(0, Number(prepared.config.storage.maxLogs || 500));

return [{
  json: {
    ok: !errorMessage && Boolean(responseData.call_control_id),
    attempt_id: attemptId,
    lead_id: attempt.lead_id,
    call_control_id: attempt.call_control_id || null,
    status: store.leads[attempt.lead_id].status
  }
}];

