const env = process.env;
const defaultLeadSource = {
  mode: 'static',
  maxBatchSize: 1,
  maxRetries: 2,
  retryDelayMinutes: 15,
  testLeads: []
};
const defaultStorage = {
  mode: 'workflow_static',
  processedEventTtlHours: 168,
  maxEventHistoryPerAttempt: 25,
  maxLogs: 500
};
const leadSource = parseJson(env.LEAD_SOURCE_CONFIG, defaultLeadSource);
const storage = parseJson(env.STORAGE_CONFIG, defaultStorage);
const baseInput = env.N8N_PUBLIC_WEBHOOK_URL || 'https://YOUR_N8N_HOST';
const publicWebhookBase = baseInput.replace(/\/$/, '').replace(/\/webhook\/.*$/, '');

return [{
  json: {
    config: {
      telnyxApiBase: 'https://api.telnyx.com/v2',
      telnyxApiKey: env.TELNYX_API_KEY || 'TELNYX_API_KEY',
      telnyxConnectionId: env.TELNYX_CONNECTION_ID || 'TELNYX_CONNECTION_ID',
      telnyxFromNumber: env.TELNYX_FROM_NUMBER || 'TELNYX_FROM_NUMBER',
      myPhoneNumber: env.MY_PHONE_NUMBER || 'MY_PHONE_NUMBER',
      publicWebhookBase,
      telnyxWebhookUrl: publicWebhookBase + '/webhook/telnyx-power-dialer-events',
      leadSource,
      storage,
      maxRetries: Number(leadSource.maxRetries ?? 2),
      retryDelayMinutes: Number(leadSource.retryDelayMinutes ?? 15),
      maxBatchSize: Number(leadSource.maxBatchSize ?? 1),
      humanResults: ['human', 'human_residence', 'human_business'],
      nonHumanResults: ['machine', 'silence', 'fax_detected', 'not_sure'],
      busyCauses: ['busy', 'user_busy'],
      noAnswerCauses: ['no_answer', 'timeout', 'no_response'],
      invalidCauses: ['unallocated_number', 'invalid_number_format', 'no_route_destination'],
      failedCauses: ['call_rejected', 'service_unavailable', 'incompatible_destination', 'system_shutdown', 'normal_temp_failure']
    },
    trigger: $input.first() ? $input.first().json : {}
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.dialer = staticData.dialer || { leads: {}, attempts: {}, processedEvents: {}, logs: [] };
const store = staticData.dialer;
const config = $json.config;
const body = $json.trigger.body || $json.trigger || {};
const leadId = body.lead_id || null;

let attempt = null;
if (body.attempt_id && store.attempts?.[body.attempt_id]) {
  attempt = store.attempts[body.attempt_id];
} else if (leadId && store.leads?.[leadId]?.current_attempt_id && store.attempts?.[store.leads[leadId].current_attempt_id]) {
  attempt = store.attempts[store.leads[leadId].current_attempt_id];
} else if (leadId) {
  attempt = Object.values(store.attempts || {})
    .filter((item) => item.lead_id === leadId)
    .sort((a, b) => String(b.initiated_at || '').localeCompare(String(a.initiated_at || '')))[0] || null;
}

const fallbackAttemptId = body.attempt_id || (leadId ? leadId + '-synthetic-1' : 'synthetic-attempt-1');
const clientStatePayload = attempt?.client_state_payload || {
  lead_id: leadId || 'synthetic-lead',
  attempt_id: fallbackAttemptId,
  attempt_number: body.attempt_number || 1
};
const clientState = body.client_state || attempt?.client_state || Buffer.from(JSON.stringify(clientStatePayload)).toString('base64');

const syntheticEvent = {
  headers: $json.trigger.headers || {},
  body: {
    data: {
      record_type: 'event',
      event_type: body.event_type || 'call.machine.premium.detection.ended',
      id: body.event_id || 'test-' + Date.now(),
      occurred_at: new Date().toISOString(),
      payload: {
        call_control_id: body.call_control_id || attempt?.call_control_id || 'test-call-control-id',
        call_session_id: body.call_session_id || attempt?.call_session_id || fallbackAttemptId,
        call_leg_id: body.call_leg_id || attempt?.call_leg_id || 'test-call-leg-id',
        client_state: clientState,
        result: body.result || null,
        hangup_cause: body.hangup_cause || null,
        hangup_source: body.hangup_source || 'callee',
        state: body.state || null,
        from: body.from || config.telnyxFromNumber,
        to: body.to || attempt?.lead_phone || body.phone || 'LEAD_PHONE_PLACEHOLDER'
      }
    },
    isSynthetic: true
  }
};

return [{
  json: {
    config,
    trigger: syntheticEvent
  }
}];

const config = $json.config;
const trigger = $json.trigger || {};
const envelope = trigger.body?.data ? trigger.body.data : (trigger.data ? trigger.data : null);
const payload = envelope?.payload || {};
let clientStateDecoded = null;

if (payload.client_state) {
  try {
    const decoded = Buffer.from(payload.client_state, 'base64').toString('utf8');
    clientStateDecoded = JSON.parse(decoded);
  } catch {
    clientStateDecoded = { raw: payload.client_state };
  }
}

const errors = [];
if (!envelope?.event_type) errors.push('Missing data.event_type');
if (!payload.call_control_id) errors.push('Missing payload.call_control_id');

return [{
  json: {
    config,
    well_formed: errors.length === 0,
    errors,
    headers: trigger.headers || {},
    raw_event: trigger.body || trigger,
    event_id: envelope?.id || null,
    occurred_at: envelope?.occurred_at || new Date().toISOString(),
    event_type: envelope?.event_type || null,
    call_control_id: payload.call_control_id || null,
    call_session_id: payload.call_session_id || null,
    call_leg_id: payload.call_leg_id || null,
    client_state: payload.client_state || null,
    client_state_decoded: clientStateDecoded,
    attempt_id: clientStateDecoded?.attempt_id || null,
    lead_id: clientStateDecoded?.lead_id || null,
    attempt_number: clientStateDecoded?.attempt_number || null,
    amd_result: payload.result || null,
    hangup_cause: payload.hangup_cause || null,
    hangup_source: payload.hangup_source || null,
    payload,
    is_synthetic: Boolean(trigger.body?.isSynthetic)
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.dialer = staticData.dialer || { leads: {}, attempts: {}, processedEvents: {}, logs: [] };
const store = staticData.dialer;
const nowIso = new Date().toISOString();
store.logs.unshift({
  at: nowIso,
  kind: 'malformed_event',
  errors: $json.errors,
  raw: $json.raw_event
});
store.logs = store.logs.slice(0, Number($json.config.storage.maxLogs || 500));
return [{
  json: {
    ok: true,
    ignored: true,
    reason: 'Malformed event logged',
    errors: $json.errors
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.dialer = staticData.dialer || { leads: {}, attempts: {}, processedEvents: {}, logs: [] };
const store = staticData.dialer;
const config = $json.config;
const now = Date.now();
const ttlMs = Number(config.storage.processedEventTtlHours || 168) * 60 * 60 * 1000;

for (const [eventId, seenAt] of Object.entries(store.processedEvents || {})) {
  if (!seenAt) continue;
  const age = now - new Date(seenAt).getTime();
  if (age > ttlMs) delete store.processedEvents[eventId];
}

let attempt = null;
if ($json.attempt_id && store.attempts?.[$json.attempt_id]) {
  attempt = store.attempts[$json.attempt_id];
}
if (!attempt && $json.call_control_id) {
  attempt = Object.values(store.attempts || {}).find((item) => item.call_control_id === $json.call_control_id) || null;
}
let lead = null;
if ($json.lead_id && store.leads?.[$json.lead_id]) {
  lead = store.leads[$json.lead_id];
}
if (!lead && attempt && store.leads?.[attempt.lead_id]) {
  lead = store.leads[attempt.lead_id];
}

const isDuplicate = Boolean($json.event_id && store.processedEvents?.[$json.event_id]);
if (!isDuplicate && $json.event_id) {
  store.processedEvents = store.processedEvents || {};
  store.processedEvents[$json.event_id] = new Date().toISOString();
}

return [{
  json: {
    ...$json,
    attempt_id: attempt?.attempt_id || $json.attempt_id || null,
    lead_id: lead?.id || attempt?.lead_id || $json.lead_id || null,
    attempt: attempt || null,
    lead: lead || null,
    is_duplicate: isDuplicate
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.dialer = staticData.dialer || { leads: {}, attempts: {}, processedEvents: {}, logs: [] };
const store = staticData.dialer;
const nowIso = new Date().toISOString();
store.logs.unshift({
  at: nowIso,
  kind: 'duplicate_event',
  event_id: $json.event_id,
  event_type: $json.event_type,
  lead_id: $json.lead_id,
  attempt_id: $json.attempt_id
});
store.logs = store.logs.slice(0, Number($json.config.storage.maxLogs || 500));
return [{
  json: {
    ok: true,
    ignored: true,
    reason: 'Duplicate event ignored',
    event_id: $json.event_id
  }
}];

const config = $json.config;
const attempt = $json.attempt || {};
const lead = $json.lead || {};
const eventType = String($json.event_type || '').toLowerCase();
const amdResult = String($json.amd_result || '').toLowerCase();
const hangupCause = String($json.hangup_cause || '').toLowerCase();
const transferStatus = attempt.transfer?.status || 'not_requested';

let normalizedOutcome = null;
let summaryStatus = lead.status || attempt.status || 'unknown';
let needsTransfer = false;
let needsMachineHangup = false;
let shouldRetry = false;
let retryDueAt = null;
let note = 'log_only';

if (eventType === 'call.machine.premium.detection.ended') {
  if (config.humanResults.includes(amdResult)) {
    normalizedOutcome = amdResult;
    summaryStatus = 'amd_human';
    needsTransfer = !['requested', 'succeeded'].includes(transferStatus);
    note = needsTransfer ? 'human_detected_transfer_now' : 'human_detected_transfer_already_requested';
  } else if (config.nonHumanResults.includes(amdResult)) {
    normalizedOutcome = amdResult;
    summaryStatus = amdResult;
    needsMachineHangup = true;
    note = 'non_human_detected';
  } else {
    normalizedOutcome = amdResult || 'unknown_amd_result';
    summaryStatus = 'unknown_amd_result';
    note = 'unknown_amd_result';
  }
} else if (eventType === 'call.bridged') {
  normalizedOutcome = 'human_transferred';
  summaryStatus = 'transferred';
  note = 'bridge_confirmed';
} else if (eventType === 'call.hangup') {
  if (config.busyCauses.includes(hangupCause)) {
    normalizedOutcome = 'busy';
    summaryStatus = 'busy';
    shouldRetry = true;
    note = 'busy';
  } else if (config.noAnswerCauses.includes(hangupCause)) {
    normalizedOutcome = 'no_answer';
    summaryStatus = 'no_answer';
    shouldRetry = true;
    note = 'no_answer';
  } else if (config.invalidCauses.includes(hangupCause)) {
    normalizedOutcome = 'invalid';
    summaryStatus = 'invalid';
    note = 'invalid_number';
  } else if (hangupCause === 'originator_cancel' || hangupCause === 'normal_clearing') {
    normalizedOutcome = 'completed';
    summaryStatus = 'completed';
    note = 'completed';
  } else if (hangupCause) {
    normalizedOutcome = 'failed';
    summaryStatus = 'failed';
    note = 'failed';
  } else {
    normalizedOutcome = 'hung_up';
    summaryStatus = 'hung_up';
    note = 'hung_up';
  }

  if (transferStatus === 'requested' && normalizedOutcome !== 'completed') {
    normalizedOutcome = 'transfer_failed';
    summaryStatus = 'transfer_failed';
    shouldRetry = false;
    note = 'transfer_failed_before_bridge';
  }
} else if (eventType === 'call.answered') {
  normalizedOutcome = 'answered';
  summaryStatus = 'answered';
  note = 'answered_waiting_for_amd';
} else if (eventType === 'call.initiated') {
  normalizedOutcome = 'call_initiated';
  summaryStatus = 'call_initiated';
  note = 'initiated';
} else {
  normalizedOutcome = eventType || 'unknown_event';
  summaryStatus = lead.status || attempt.status || 'unknown';
  note = 'log_only';
}

const attemptsUsed = Number(attempt.attempt_number || $json.attempt_number || lead.attempts || 1);
const retriesUsed = Math.max(0, attemptsUsed - 1);
const canRetry = shouldRetry && retriesUsed < Number(config.maxRetries || 0);
if (canRetry) {
  retryDueAt = new Date(Date.now() + Number(config.retryDelayMinutes || 15) * 60 * 1000).toISOString();
}

return [{
  json: {
    ...$json,
    normalized_outcome: normalizedOutcome,
    summary_status: summaryStatus,
    note,
    needs_transfer: needsTransfer,
    needs_machine_hangup: needsMachineHangup,
    should_retry: canRetry,
    retry_due_at: retryDueAt
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.dialer = staticData.dialer || { leads: {}, attempts: {}, processedEvents: {}, logs: [] };
const store = staticData.dialer;
const nowIso = new Date().toISOString();
const attemptId = $json.attempt_id || $json.attempt?.attempt_id;
const attempt = store.attempts?.[attemptId] || $json.attempt || {};
const lead = store.leads?.[attempt.lead_id] || $json.lead || {};
const transferCommandId = (attempt.transfer?.command_id || ('transfer-' + attemptId)).slice(0, 128);

attempt.transfer = {
