  status: 'requested',
  command_id: transferCommandId,
  requested_at: attempt.transfer?.requested_at || nowIso
};
attempt.status = 'transfer_requested';
store.attempts[attemptId] = attempt;

store.leads[attempt.lead_id] = {
  ...lead,
  status: 'transfer_requested',
  transfer_happened: false,
  updated_at: nowIso
};

store.logs.unshift({
