const staticData = $getWorkflowStaticData('global');
staticData.dialer = staticData.dialer || { leads: {}, attempts: {}, processedEvents: {}, logs: [] };
const store = staticData.dialer;
const config = $json.config;
const nowIso = new Date().toISOString();
let attempt = $json.attempt || null;
if (!attempt && $json.attempt_id && store.attempts?.[$json.attempt_id]) {
  attempt = store.attempts[$json.attempt_id];
}
if (!attempt && $json.call_control_id) {
  attempt = Object.values(store.attempts || {}).find((item) => item.call_control_id === $json.call_control_id) || null;
}

if (!attempt) {
  store.logs.unshift({
    at: nowIso,
    kind: 'unmatched_event',
    event_id: $json.event_id,
    event_type: $json.event_type,
    call_control_id: $json.call_control_id
  });
  store.logs = store.logs.slice(0, Number(config.storage.maxLogs || 500));
  return [{
    json: {
      ok: true,
      ignored: true,
      reason: 'No matching attempt found for event',
      event_type: $json.event_type
    }
  }];
}

const lead = store.leads?.[attempt.lead_id] || $json.lead || { id: attempt.lead_id };
attempt.history = attempt.history || [];
attempt.history.push({
  at: $json.occurred_at || nowIso,
  event_id: $json.event_id,
  event_type: $json.event_type,
  outcome: $json.normalized_outcome,
  note: $json.note
});
attempt.history = attempt.history.slice(-Number(config.storage.maxEventHistoryPerAttempt || 25));

if ($json.event_type === 'call.bridged') {
  attempt.status = 'transferred';
  attempt.last_result = 'human_transferred';
  attempt.final_result = 'human_transferred';
  attempt.completed_at = nowIso;
  attempt.transfer = {
    ...(attempt.transfer || {}),
    status: 'succeeded',
    succeeded_at: nowIso,
    error: null
  };
  store.leads[attempt.lead_id] = {
    ...lead,
    status: 'transferred',
    last_result: 'human_transferred',
    transfer_happened: true,
    current_attempt_id: null,
    active_call_control_id: null,
    next_retry_at: null,
    updated_at: nowIso
  };
} else if ($json.should_retry) {
  attempt.status = 'retry_scheduled';
  attempt.last_result = $json.normalized_outcome;
  attempt.final_result = $json.normalized_outcome;
  attempt.next_retry_at = $json.retry_due_at;
  attempt.completed_at = nowIso;
  store.leads[attempt.lead_id] = {
    ...lead,
    status: 'retry_scheduled',
    last_result: $json.normalized_outcome,
    next_retry_at: $json.retry_due_at,
    current_attempt_id: null,
    active_call_control_id: null,
    updated_at: nowIso
  };
} else if (['invalid', 'failed', 'completed', 'hung_up', 'transfer_failed'].includes($json.normalized_outcome)) {
  attempt.status = $json.summary_status;
  attempt.last_result = $json.normalized_outcome;
  attempt.final_result = $json.normalized_outcome;
  attempt.completed_at = nowIso;
  if ($json.normalized_outcome === 'transfer_failed') {
    attempt.transfer = {
      ...(attempt.transfer || {}),
      status: 'failed',
      failed_at: nowIso,
      error: attempt.transfer?.error || 'Lead leg ended before bridge completed'
    };
  }
  store.leads[attempt.lead_id] = {
    ...lead,
    status: $json.summary_status,
    last_result: $json.normalized_outcome,
    current_attempt_id: null,
    active_call_control_id: null,
    next_retry_at: null,
    updated_at: nowIso
  };
} else if (['answered', 'call_initiated'].includes($json.normalized_outcome)) {
  attempt.status = $json.summary_status;
  attempt.last_result = $json.normalized_outcome;
  store.leads[attempt.lead_id] = {
    ...lead,
    status: $json.summary_status,
    active_call_control_id: attempt.call_control_id || $json.call_control_id || lead.active_call_control_id || null,
    current_attempt_id: attempt.attempt_id,
    updated_at: nowIso
  };
} else {
  attempt.status = $json.summary_status;
  attempt.last_result = $json.normalized_outcome;
  store.leads[attempt.lead_id] = {
    ...lead,
    status: $json.summary_status,
    updated_at: nowIso
  };
}

store.attempts[attempt.attempt_id] = attempt;
store.logs.unshift({
  at: nowIso,
  kind: 'event_finalized',
  lead_id: attempt.lead_id,
  attempt_id: attempt.attempt_id,
  event_type: $json.event_type,
  outcome: $json.normalized_outcome,
  status: store.leads[attempt.lead_id].status,
  retry_due_at: store.leads[attempt.lead_id].next_retry_at || null
});
store.logs = store.logs.slice(0, Number(config.storage.maxLogs || 500));

return [{
  json: {
    ok: true,
    lead_id: attempt.lead_id,
    attempt_id: attempt.attempt_id,
    status: store.leads[attempt.lead_id].status,
    outcome: $json.normalized_outcome,
    should_retry: $json.should_retry,
    retry_due_at: store.leads[attempt.lead_id].next_retry_at || null
  }
}];
